		public void TestHelperForvalidMessage()
		{
			var testInterchange = Factory.NewWithValidTestData<EDIInterchange>();
			var testMessage = (ZAMessage)testInterchange.ContainedMessages.AddNew(typeof(ZAMessage));
			testMessage.EM_MessageText = CUSDEC_BGM9_Message;
			var testHelper = CUSDECMessageHelper.New(testMessage);
			CombineAssertions(() =>
			{
				AssertNotNull(testHelper);
				AssertEquals("PaymentParty", "D", testHelper.PaymentMethod);
				AssertEquals("MessageFunctionCode", "9", testHelper.MessageType);
				AssertEquals("InterchangeTime", ZDateTime.Empty, testHelper.InterchangeTime);
				AssertEquals("TDD", 675.00m, testHelper.GetDutyOrTaxAmount("TDD"));
				AssertEquals("TVD", 441.00m, testHelper.GetDutyOrTaxAmount("TVD"));
			});
		}

